import unittest

from ratelimit.bucket import TokenBucket


class BucketContractTest(unittest.TestCase):
    def bucket(self, rate: float = 1.0, capacity: int = 5):
        now = [0.0]
        return TokenBucket(rate=rate, capacity=capacity, clock=lambda: now[0]), now

    def test_the_bucket_starts_full(self) -> None:
        bucket, _ = self.bucket(capacity=3)
        self.assertTrue(bucket.allow(3))
        self.assertFalse(bucket.allow())

    def test_refill_is_capped_at_capacity(self) -> None:
        bucket, now = self.bucket(rate=1.0, capacity=3)
        bucket.allow(3)
        now[0] = 1000.0
        self.assertTrue(bucket.allow(3))
        self.assertFalse(bucket.allow())

    def test_partial_refill_grants_exactly_what_accrued(self) -> None:
        bucket, now = self.bucket(rate=2.0, capacity=4)
        bucket.allow(4)
        now[0] = 1.0
        self.assertTrue(bucket.allow(2))
        self.assertFalse(bucket.allow())

    def test_a_request_larger_than_capacity_consumes_nothing(self) -> None:
        bucket, _ = self.bucket(capacity=5)
        self.assertFalse(bucket.allow(6))
        self.assertTrue(bucket.allow(5))

    def test_a_non_positive_request_is_rejected(self) -> None:
        bucket, _ = self.bucket()
        with self.assertRaises(ValueError):
            bucket.allow(0)
        with self.assertRaises(ValueError):
            bucket.allow(-1)

    def test_a_backwards_clock_creates_nothing(self) -> None:
        bucket, now = self.bucket(rate=1.0, capacity=5)
        bucket.allow(5)
        now[0] = -10.0
        self.assertFalse(bucket.allow())

    def test_a_backwards_clock_destroys_nothing(self) -> None:
        bucket, now = self.bucket(rate=1.0, capacity=5)
        bucket.allow(2)
        now[0] = 5.0
        now[0] = -5.0
        self.assertTrue(bucket.allow(3))

    def test_a_refused_request_is_still_an_observation(self) -> None:
        bucket, now = self.bucket(rate=1.0, capacity=10)
        bucket.allow(10)
        now[0] = 1.0
        self.assertFalse(bucket.allow(5))
        self.assertTrue(bucket.allow(1))
        self.assertFalse(bucket.allow(1))

    def test_calls_at_one_instant_do_not_compound(self) -> None:
        bucket, now = self.bucket(rate=1.0, capacity=2)
        bucket.allow(2)
        now[0] = 1.0
        self.assertFalse(bucket.allow(2))
        self.assertTrue(bucket.allow(1))

    def test_the_constructor_calls_the_clock_at_most_once(self) -> None:
        calls: list[float] = []

        def clock() -> float:
            calls.append(0.0)
            return 0.0

        TokenBucket(rate=1.0, capacity=2, clock=clock)
        self.assertLessEqual(len(calls), 1)


if __name__ == "__main__":
    unittest.main()
